const body = $input.item.json.body;
const source = body.source || 'unknown';
const from = body.from || 'Unknown';
const summary = body.summary || '';
const category = body.category || '';
const priority = body.priority || 'medium';
const eventDetails = body.event_details || null;
const suggestedActions = body.suggested_actions || [];
const notifyJosh = body.notify_josh || false;
const originalMessage = body.original_message || '';

// Determine which auto-actions to take
const actions = [];

// Auto-add to calendar if event detected with enough detail
if (eventDetails && eventDetails.title && eventDetails.date) {
  actions.push({
    type: 'add_calendar_event',
    title: eventDetails.title,
    date: eventDetails.date,
    time: eventDetails.time || null,
    location: eventDetails.location || null,
    calendar: category === 'school' ? 'school' : category === 'work' ? 'work' : 'family'
  });
}

// Auto-notify Josh for family/school items where he should know
if (notifyJosh || (category === 'school' && priority !== 'low') || suggestedActions.includes('notify_josh')) {
  actions.push({
    type: 'notify_josh',
    message: summary
  });
}

// Auto-set reminder for items with deadlines
if (suggestedActions.includes('rsvp') || suggestedActions.includes('set_reminder')) {
  const reminderDate = eventDetails?.date
    ? new Date(new Date(eventDetails.date).getTime() - 86400000).toISOString()
    : new Date(Date.now() + 86400000).toISOString();
  actions.push({
    type: 'set_reminder',
    message: `Don't forget: ${summary}`,
    scheduledFor: reminderDate
  });
}

// Build Claude prompt to compose the notification message
const prompt = `You are LifeSync, a family life assistant. You just automatically took action on something you found. Compose a SHORT text message (under 400 chars) telling the parent what you found and what you did about it.

Be conversational and confident, like a helpful assistant reporting back. Use first person ("I saw...", "I've added...", "I noticed...").

Source: ${source === 'gmail' ? 'Email' : source === 'sms' ? 'Text message' : source}
From: ${from}
What was found: ${summary}
Category: ${category}

Actions taken:
${actions.map(a => {
  switch(a.type) {
    case 'add_calendar_event': return `- Added "${a.title}" to the ${a.calendar} calendar${a.date ? ' on ' + a.date : ''}${a.time ? ' at ' + a.time : ''}`;
    case 'notify_josh': return '- Notified Josh';
    case 'set_reminder': return `- Set a reminder: ${a.message}`;
    default: return `- ${a.type}`;
  }
}).join('\n')}

Keep it natural and brief. Example tone: "I saw Sarah invited Emma to her birthday party on March 15 — added it to the family calendar and Josh has been notified!"`;

return [{ json: { prompt, actions, source, from, summary, category, priority, eventDetails, notifyJosh } }];

const data = $input.item.json;
const actions = data.actions;
const results = [];

for (const action of actions) {
  switch(action.type) {
    case 'add_calendar_event': {
      // Prepare calendar event data for the Google Calendar node
      const startDate = action.date;
      let startDateTime = null;
      let allDay = true;
      if (action.time) {
        // Parse time like "2:00 PM" or "14:00"
        const timeParts = action.time.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
        if (timeParts) {
          let hours = parseInt(timeParts[1]);
          const mins = timeParts[2];
          if (timeParts[3]?.toUpperCase() === 'PM' && hours < 12) hours += 12;
          if (timeParts[3]?.toUpperCase() === 'AM' && hours === 12) hours = 0;
          startDateTime = `${startDate}T${String(hours).padStart(2, '0')}:${mins}:00`;
          allDay = false;
        }
      }
      results.push({
        actionType: 'calendar',
        title: action.title,
        startDate: allDay ? startDate : startDateTime,
        endDate: allDay ? startDate : new Date(new Date(startDateTime).getTime() + 3600000).toISOString(),
        location: action.location || '',
        allDay,
        calendar: action.calendar
      });
      break;
    }
    case 'notify_josh': {
      results.push({
        actionType: 'notify_josh',
        message: action.message
      });
      break;
    }
    case 'set_reminder': {
      results.push({
        actionType: 'reminder',
        message: action.message,
        scheduledFor: action.scheduledFor
      });
      break;
    }
  }
}

return results.map(r => ({ json: { ...r, originalData: { source: data.source, from: data.from, summary: data.summary, prompt: data.prompt } } }));
